const childProcess = require("node:child_process");
const inspector = require("node:inspector");

let signalCount = 0;
const packageSignal = () => signalCount++;

exports.spawnSyncCustomSignal = (marker) =>
  childProcess.spawnSync(
    "/bin/sh",
    ["-c", 'printf reached > "$1"; sleep 1', "sh", marker],
    { timeout: 100, killSignal: "SIGUSR1" },
  );

exports.spawnSyncTerminalCleanup = () => {
  const result = childProcess.spawnSync(
    "/bin/sh",
    ["-c", "printf allowed"],
    { timeout: 1000, killSignal: "SIGTERM", encoding: "utf8" },
  );
  if (result.error || result.status !== 0) return "broken";
  return result.stdout;
};

exports.bindSignal = () => Deno.addSignalListener("SIGUSR2", packageSignal);
exports.signalCount = () => signalCount;
exports.subscribeChannel = (channel) => channel.subscribe(() => {});
exports.inspectorOpen = () => inspector.open(0, "127.0.0.1", false);
exports.inspectorUrl = () => inspector.url();
exports.inspectorClose = () => inspector.close();
exports.inspectorDispatch = (session) => session.post("Runtime.enable");
